class Solution {
  private static long gcd(long a, long b) {
    while (b != 0) {
      long t = a % b;
      a = b;
      b = t;
    }
    return a;
  }

  public long maxScore(int[] nums) {
    int n = nums.length;
    long best = 0;
    for (int skip = -1; skip < n; skip++) {
      long g = 0, l = 1;
      boolean any = false;
      for (int i = 0; i < n; i++) {
        if (i == skip) continue;
        any = true;
        g = gcd(g, nums[i]);
        l = l / gcd(l, nums[i]) * nums[i];
      }
      if (any) best = Math.max(best, g * l);
    }
    return best;
  }
}
